@startuml

class OOBank {}

class Branch {
  + address : string
  + branchNumber : int
}

class Division {
  + name : string
}

class Subdivision {
  + name : string
}

class Employee {
  + name : string
}

class Customer {
  + name : string
}

class Account {
  + accountNumber : int
  + balance : double
  + creditOrOverdraftLimit : double
  + interestRate : float
  + monthlyFee : float
}

class Privilege {
  + description : string
}

class MortgageAccount extends Account {
  + propertyCollateral : string
}

class CheckingAccount extends Account {}

class CreditCardAccount extends Account {
  + expiryDate : date
}

class SecondaryCard {}

class JointAccount extends Account {}

OOBank "1" *-- "*" Division
OOBank "1" *-- "*" Branch
Division "1" *-- "*" Subdivision
Division "1" -- "1" Employee : manager
Division "1" -- "*" Employee
Subdivision "1" -- "*" Branch
Branch "1" -- "*" Account : hosts
Branch "1" -- "*" Customer : hosts
Customer "1" -- "*" Account : owns
Customer "1" -- "0..*" Account : joint owner
Customer "*" -- "1" Employee : personal banker
Account "*" -- "*" Privilege : has

CreditCardAccount "1" -- "*" SecondaryCard : has
JointAccount "*" -- "2" Customer : held by

@enduml

